/** True when `role` is at least as privileged as `atLeast`. */
export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}

/**
 * Seat quota. `owner`, `admin` and `member` each occupy one seat. A `viewer`
 * is free and never counts against the plan.
 */
export function isBillableRole(role: Role): boolean {
  return role === "owner" || role === "admin" || role === "member";
}

/**
 * Seats currently held against a plan: billable active members, plus pending
 * invitations (not accepted, not revoked) for a billable role.
 */
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import type { OrgId } from "@/types/common";

export async function billableSeatsInUse(orgId: OrgId): Promise<number> {
  const [members, pending] = await Promise.all([
    memberRepo.countActiveBillableMembers(orgId),
    invitationRepo.countPendingBillableInvitations(orgId),
  ]);
  return members + pending;
}

