/** Live members of every role. Not the seat count — viewers are members too. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  return countMembers(orgId, false);
}

/** Active members whose role occupies a seat. Viewers are excluded. */
export async function countActiveBillableMembers(orgId: OrgId): Promise<number> {
  return countMembers(orgId, true);
}

async function countMembers(orgId: OrgId, billableOnly: boolean): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        ...compact(
          orgPredicate(members.orgId, orgId),
          eq(members.status, "active"),
          liveMemberPredicate(),
          billableOnly ? inArray(members.role, [...BILLABLE_ROLES]) : undefined,
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

