    const delta = billableSeatDelta(payload.from, payload.to);
    if (delta === 0) return;
    const member = await memberRepo.findMemberById(
      payload.orgId,
      payload.memberId,
    );
    if (!member || member.status !== "active" || member.archivedAt !== null) {
      return;
    }
