/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

/** How a role change moves the billable-seat counter. Zero when both sides match. */
function billableSeatDelta(from: Role, to: Role): number {
  return (isBillableRole(to) ? 1 : 0) - (isBillableRole(from) ? 1 : 0);
}

